import { useMemo } from 'react';

import { useSourcesListQuery } from 'entities/Source';
import { SOURSCES_LIMIT } from 'features/Filters';

export const useSourceSelect = () => {
	const { data: sourceList, isFetching: isSourceLoading } = useSourcesListQuery({ limit: SOURSCES_LIMIT });
	const sourceOptions = useMemo(
		() => sourceList?.results?.map(({ name, uuid }) => ({ label: name, value: uuid })) || [],
		[sourceList],
	);
	return { sourceOptions, isSourceLoading };
};
